use crate::io::{AsyncRead, AsyncWrite, ReadBuf};

use bytes::Buf;
use pin_project_lite::pin_project;
use std::future::Future;
use std::io;
use std::marker::PhantomPinned;
use std::pin::Pin;
use std::task::{Context, Poll};

use super::copy_bidirectional::CopyBuffer;

pin_project! {
    /// A future to write some of the buffer to an `AsyncWrite`.
    #[derive(Debug)]
    #[must_use = "futures do nothing unless you `.await` or poll them"]
    pub struct WriteAllBuf<'a, W: ?Sized, B> {
        writer: &'a mut W,
        buf: &'a mut B,
        #[pin]
        _pin: PhantomPinned,
    }
}

/// Tries to write some bytes from the given `buf` to the writer in an
/// asynchronous manner, returning a future.
pub(crate) fn write_all_buf<'a, W, B>(writer: &'a mut W, buf: &'a mut B) -> WriteAllBuf<'a, W, B>
where
    W: AsyncWrite + Unpin + ?Sized,
    B: Buf,
{
    WriteAllBuf {
        writer,
        buf,
        _pin: PhantomPinned,
    }
}

impl<W, B> WriteAllBuf<'_, W, B>
where
    W: AsyncWrite + Unpin + ?Sized,
    B: Buf,
{
    pub(super) fn poll_copy<R>(
        &mut self,
        copy: &mut CopyBuffer,
        cx: &mut Context<'_>,
        mut reader: Pin<&mut R>,
    ) -> Poll<io::Result<u64>>
    where
        R: AsyncRead + ?Sized,
    {
        let user_remaining = self.buf.remaining();

        ready!(crate::trace::trace_leaf(cx));
        #[cfg(any(
            feature = "fs",
            feature = "io-std",
            feature = "net",
            feature = "process",
            feature = "rt",
            feature = "signal",
            feature = "sync",
            feature = "time",
        ))]
        let coop = ready!(crate::runtime::coop::poll_proceed(cx));
        loop {
            if copy.cap < copy.buf.len() && !copy.read_done {
                let mut read_buf = ReadBuf::new(&mut copy.buf[..]);
                read_buf.set_filled(copy.cap);
                let unfilled = read_buf.remaining();
                let fill_res = if unfilled == 0 {
                    Poll::Ready(Ok(()))
                } else {
                    reader.as_mut().poll_read(cx, &mut read_buf)
                };
                match fill_res {
                    Poll::Ready(Ok(())) => {
                        if unfilled > 0 {
                            let filled_len = read_buf.filled().len();
                            let initialized_len = read_buf.initialized().len();
                            copy.read_done = copy.cap == filled_len;
                            copy.cap = filled_len.min(initialized_len);
                        }
                        #[cfg(any(
                            feature = "fs",
                            feature = "io-std",
                            feature = "net",
                            feature = "process",
                            feature = "rt",
                            feature = "signal",
                            feature = "sync",
                            feature = "time",
                        ))]
                        coop.made_progress();
                    }
                    Poll::Ready(Err(err)) => {
                        #[cfg(any(
                            feature = "fs",
                            feature = "io-std",
                            feature = "net",
                            feature = "process",
                            feature = "rt",
                            feature = "signal",
                            feature = "sync",
                            feature = "time",
                        ))]
                        coop.made_progress();
                        return Poll::Ready(Err(err));
                    }
                    Poll::Pending => {
                        if user_remaining.saturating_add(copy.cap.saturating_sub(copy.pos))
                            == user_remaining
                        {
                            if copy.need_flush {
                                ready!(Pin::new(&mut *self.writer).poll_flush(cx))?;
                                #[cfg(any(
                                    feature = "fs",
                                    feature = "io-std",
                                    feature = "net",
                                    feature = "process",
                                    feature = "rt",
                                    feature = "signal",
                                    feature = "sync",
                                    feature = "time",
                                ))]
                                coop.made_progress();
                                copy.need_flush = false;
                            }

                            return Poll::Pending;
                        }
                    }
                }
            }

            while copy.pos < copy.cap {
                let n = {
                    match Pin::new(&mut *self.writer).poll_write(cx, &copy.buf[copy.pos..copy.cap]) {
                        Poll::Pending => {
                            if !copy.read_done && copy.cap < copy.buf.len() {
                                let mut read_buf = ReadBuf::new(&mut copy.buf[..]);
                                read_buf.set_filled(copy.cap);
                                if read_buf.remaining() > 0 {
                                    ready!(reader.as_mut().poll_read(cx, &mut read_buf))?;
                                    let filled_len = read_buf.filled().len();
                                    let initialized_len = read_buf.initialized().len();
                                    copy.read_done = copy.cap == filled_len;
                                    copy.cap = filled_len.min(initialized_len);
                                }
                            }
                            return Poll::Pending;
                        }
                        Poll::Ready(Ok(n)) => n,
                        Poll::Ready(Err(err)) => return Poll::Ready(Err(err)),
                    }
                };
                #[cfg(any(
                    feature = "fs",
                    feature = "io-std",
                    feature = "net",
                    feature = "process",
                    feature = "rt",
                    feature = "signal",
                    feature = "sync",
                    feature = "time",
                ))]
                coop.made_progress();
                if n == 0 {
                    return Poll::Ready(Err(io::Error::new(
                        io::ErrorKind::WriteZero,
                        "write zero byte into writer",
                    )));
                } else {
                    copy.pos += n;
                    copy.amt += n as u64;
                    copy.need_flush = true;
                }
            }

            debug_assert!(
                copy.pos <= copy.cap,
                "writer returned length larger than input slice"
            );

            copy.pos = 0;
            copy.cap = 0;

            if copy.read_done {
                ready!(Pin::new(&mut *self.writer).poll_flush(cx))?;
                #[cfg(any(
                    feature = "fs",
                    feature = "io-std",
                    feature = "net",
                    feature = "process",
                    feature = "rt",
                    feature = "signal",
                    feature = "sync",
                    feature = "time",
                ))]
                coop.made_progress();
                return Poll::Ready(Ok(copy.amt));
            }
        }
    }
}

impl<W, B> Future for WriteAllBuf<'_, W, B>
where
    W: AsyncWrite + Unpin + ?Sized,
    B: Buf,
{
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        let me = self.project();
        while me.buf.has_remaining() {
            let n = ready!(Pin::new(&mut *me.writer).poll_write(cx, me.buf.chunk())?);
            me.buf.advance(n);
            if n == 0 {
                return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
            }
        }

        Poll::Ready(Ok(()))
    }
}

